701	# 不同版本取值不同（历史上 999、32766，较新版本 250000），因此以运行时
702	# 查询为准；批量修改一次选择的客户数可能超过它，不能把全部编号塞进单条
703	# 语句的 IN(?,…)，必须分块执行。
704	DEFAULT_SQL_VARIABLE_LIMIT = 999
