708	def sql_variable_limit(database):
709	    """返回运行时 SQLite 单条语句可绑定的最大参数数量。
710	
711	    取自编译选项 MAX_VARIABLE_NUMBER（各 SQLite 版本默认值不同：999、32766、
712	    250000）；取不到时回退到保守的历史默认值 999。
713	    """
714	    try:
715	        for (option,) in database.execute("PRAGMA compile_options"):
716	            if option.startswith(COMPILE_OPTION_PREFIX):
717	                limit = int(option[len(COMPILE_OPTION_PREFIX):])
718	                if limit > 0:
719	                    return limit
720	    except (sqlite3.DatabaseError, ValueError):
