839	def parse_csv(text):
840	    """解析 RFC 4180 风格 CSV，返回 (header, data_rows)。
841	
842	    支持引号包裹的字段、引号内逗号与换行、双引号转义；
843	    引号外支持 LF / CRLF / CR 换行。结构损坏时抛 FileError：
844	    - 未加引号的字段中出现双引号（双引号只能在字段开头用于包住整个字段）；
845	    - 结束引号后出现逗号、换行或文件结束以外的字符（含空格）；
846	    - 文件结束时仍有字段处于引号内（引号未闭合）。
847	    错误信息区分上述三种情况，并指出发生在表头还是第 N 条数据记录
848	    （数据记录编号不包含表头，引号字段内的换行不增加编号）。
849	    """
850	    rows = []
851	    record = []
852	    field = []
853	    quoted = False        # 当前字段处于引号内
854	    started = False       # 当前字段已经开始（已有内容或已进入引号）
855	    closed = False       # 引号字段刚结束，等待逗号 / 换行 / 文件结束
856	    record_number = 0     # 0 = 表头，1 起为数据记录
857	    i = 0
858	    n = len(text)
859	
860	    def location():
861	        return "表头" if record_number == 0 else "第 %d 条数据记录" % record_number
862	
863	    def structure_error(kind):
864	        raise FileError("CSV 结构损坏（%s）：%s" % (location(), kind))
865	
866	    def finish_record():
867	        nonlocal record, field, started, closed
868	        record.append("".join(field))
869	        rows.append(record)
870	        record = []
871	        field = []
872	        started = False
873	        closed = False
874	
875	    while i < n:
876	        c = text[i]
877	        if quoted:
878	            if c == '"':
879	                if i + 1 < n and text[i + 1] == '"':
880	                    field.append('"')
881	                    i += 2
882	                    continue
883	                quoted = False
884	                closed = True
885	                i += 1
886	                continue
887	            if c == "\r":
888	                # 统一字段内换行符为 LF
889	                if i + 1 < n and text[i + 1] == "\n":
890	                    i += 1
891	                field.append("\n")
892	                i += 1
893	                continue
894	            field.append(c)
895	            i += 1
896	            continue
897	        if closed:
898	            # 引号已结束，只允许逗号、记录换行或文件结束
899	            if c == ",":
900	                record.append("".join(field))
901	                field = []
902	                started = False
903	                closed = False
904	            elif c in "\r\n":
905	                if c == "\r" and i + 1 < n and text[i + 1] == "\n":
906	                    i += 1
907	                finish_record()
908	                record_number += 1
909	            else:
910	                structure_error("结束引号后有多余字符，结束引号后只能紧接逗号、记录换行或文件结束")
911	            i += 1
912	            continue
913	        if c == '"' and not started:
914	            quoted = True
915	            started = True
916	        elif c == '"':
917	            structure_error("未加引号的字段中出现双引号，双引号只能在字段开头用于包住整个字段")
918	        elif c == ",":
919	            record.append("".join(field))
920	            field = []
921	            started = False
922	        elif c in "\r\n":
923	            if c == "\r" and i + 1 < n and text[i + 1] == "\n":
924	                i += 1
925	            if not started and not record and not field:
926	                # 空白行：不作为数据记录（显式的 "" 空字段 started=True，仍会保留）
927	                i += 1
928	                continue
929	            finish_record()
930	            record_number += 1
931	        else:
932	            field.append(c)
933	            started = True
934	        i += 1
935	    if quoted:
936	        structure_error("引号未闭合，文件结束时仍有字段处于引号内")
937	    if started or field or record or closed:
938	        record.append("".join(field))
939	        rows.append(record)
940	    if not rows:
941	        raise FileError("CSV 内容为空：缺少表头")
