945	def check_date(value):
946	    """校验 YYYY-MM-DD 且为真实日历日期，返回 (是否合法, 错误原因)。"""
947	    match = DATE_RE.match(value)
948	    if not match:
949	        return False, "重要日期格式无效（%s）：须为 YYYY-MM-DD" % value
950	    try:
951	        datetime.date(int(match.group(1)), int(match.group(2)), int(match.group(3)))
952	    except ValueError:
953	        return False, "重要日期无效（%s）：不是真实日历日期" % value
954	    return True, None
