file.content:
// CSV 导入与批量修改共用的服务回复读取：先取回复原文，再尝试解析为 JSON。
// parsed 区分「回复确实解析成了 JSON」与「只是纯文本/空回复」：能解析成 JSON
// 却没有合格 error 或有效数量的回复，不能把整个结构当作说明或成功依据。
// 回复体读取失败时返回 null：此时不知道服务是否已经写入，调用方按无法确认处理。
async function readServiceReply(res) {
  let raw;
  try {
    raw = await res.text();
  } catch (readErr) {
    return null;
  }
  let data = null;
  let parsed = false;
  if (raw.trim()) {
    try {
      data = JSON.parse(raw);
      parsed = true;
    } catch {
      data = null;
      parsed = false;
    }
  }
  return {raw, data, parsed};
}

// CSV 导入与批量修改共用的可读原因识别：回复成功解析为 JSON 时，只接受对象中
// 的非空文本 error；其他字段、数组、字符串/数字形式的 JSON、空白或非文本 error
// 都不能作为拒绝依据。只有回复不是 JSON 结构化数据时，才把非空纯文本原文
// （去首尾空白，最多前 200 个字符）当作原因。trimJsonReason 只控制 JSON error
// 的呈现：导入去掉首尾空白，批量修改保留原文；纯文本原因两处都去首尾空白。
// 空回复同样返回空串。
function serviceReadableError(reply, trimJsonReason) {
  const {raw, data, parsed} = reply;
  if (parsed) {
    if (data && typeof data === "object" && !Array.isArray(data) &&
        typeof data.error === "string") {
      const reason = trimJsonReason ? data.error.trim() : data.error;
      if (reason.trim()) return reason;
    }
    return "";
  }
  return (raw || "").trim().slice(0, 200);
}

// CSV 导入与批量修改共用的「整次操作是否被明确拒绝」判断，两处只需维护这一处：
// 唯一能确认拒绝的情形是 HTTP 400 且从回复中识别出可读原因
// （规则见 serviceReadableError）。HTTP 400 没有可靠原因、回复读取失败、连接
// 中断，以及 HTTP 500/502 等其他非成功状态都返回 null——即使其他错误状态带有
// 原因，也不能声称客户资料未变或已经回滚，调用方一律按各自的「结果无法确认」
// 口径提示。确认拒绝时返回 {status, reason}，JSON 原因是否去首尾空白由
// trimJsonReason 决定（导入去掉、批量修改保留）。
function extractRejection(reply, status, trimJsonReason) {
  if (status !== 400) return null;
  const reason = serviceReadableError(reply, trimJsonReason);
  return reason ? {status, reason} : null;
}

// 明确拒绝时两处共用的横幅：intro 是各自功能的结论（导入说明整份文件已拒绝、
// 本次没有新增客户、原有资料保持原样；批量修改说明本次修改已全部拒绝、客户
// 资料保持原样），随后换行统一展示原因供用户修正。原因经 esc 转义，特殊字符
