// 从页面中抽出共用函数，覆盖任务列出的全部判定边界
const fs = (await import('fs')).default;
const app = fs.readFileSync('/opt/gsb-production/workspaces/coco/prod-18/B/task028/app.py','utf8');
const js = app.match(/<script>\n([\s\S]*?)<\/script>/)[1];
const name = js.match(/function serviceReadableError[\s\S]*?\n}/)[0];
const rej = js.match(/function rejectionReason[\s\S]*?\n}/)[0];
eval(name + '\n' + rej);

function replyFor(body) {
  let raw = body, data = null, parsed = false;
  if (raw.trim()) { try { data = JSON.parse(raw); parsed = true; } catch { parsed = false; } }
  return {raw, data, parsed};
}
let pass = 0, fail = 0;
function eq(label, got, want) {
  const ok = JSON.stringify(got) === JSON.stringify(want);
  console.log(ok ? 'PASS' : 'FAIL', label, ok ? '' : `got=${JSON.stringify(got)} want=${JSON.stringify(want)}`);
  ok ? pass++ : fail++;
}

// JSON：只接受对象非空文本 error
eq('对象文本 error', serviceReadableError(replyFor(JSON.stringify({error:'坏了'})), true), '坏了');
eq('其他字段 message 不算', serviceReadableError(replyFor(JSON.stringify({message:'x'})), true), '');
eq('数组不算（元素带 error 也不算）', serviceReadableError(replyFor(JSON.stringify([{error:'x'}])), true), '');
eq('字符串形式 JSON 不算', serviceReadableError(replyFor(JSON.stringify('错误原因')), true), '');
eq('数字形式 JSON 不算', serviceReadableError(replyFor('42'), true), '');
eq('null JSON 不算', serviceReadableError(replyFor('null'), true), '');
eq('空白 error 不算', serviceReadableError(replyFor(JSON.stringify({error:'  \n\t '})), true), '');
eq('数字 error 不算', serviceReadableError(replyFor(JSON.stringify({error:123})), true), '');
eq('布尔 error 不算', serviceReadableError(replyFor(JSON.stringify({error:true})), true), '');
eq('null error 不算', serviceReadableError(replyFor(JSON.stringify({error:null})), true), '');
eq('空回复不算', serviceReadableError(replyFor(''), true), '');

// JSON error 的 trim 差异：导入去首尾空白，批量保留原文
eq('导入 JSON 原因去首尾空白', serviceReadableError(replyFor(JSON.stringify({error:'  甲  '})), true), '甲');
eq('批量 JSON 原因保留原文', serviceReadableError(replyFor(JSON.stringify({error:'  甲  '})), false), '  甲  ');
eq('批量 JSON 原文内部空白保留', serviceReadableError(replyFor(JSON.stringify({error:' a\nb '})), false), ' a\nb ');

// 非 JSON 非空纯文本：两处都去首尾空白，最多前 200 字符
eq('纯文本原因', serviceReadableError(replyFor('  纯文本  \n'), true), '纯文本');
eq('纯文本原因(批量同样 trim)', serviceReadableError(replyFor('  纯文本  \n'), false), '纯文本');
eq('纯文本 200 字截断', serviceReadableError(replyFor('x'.repeat(250)), true).length, 200);
eq('纯文本 trim 后再截断', serviceReadableError(replyFor('   ' + 'y'.repeat(210)), false).length, 200);

// rejectionReason：只有 400 且有原因才确认拒绝
eq('400 + JSON 原因 → 拒绝', rejectionReason(replyFor(JSON.stringify({error:'拒'})), 400, true), '拒');
eq('400 + 纯文本原因 → 拒绝', rejectionReason(replyFor('拒绝原因'), 400, true), '拒绝原因');
eq('400 空回复 → null（无法确认）', rejectionReason(replyFor(''), 400, true), null);
eq('400 空白纯文本 → null', rejectionReason(replyFor('   '), 400, true), null);
eq('400 JSON 无合格 error → null', rejectionReason(replyFor(JSON.stringify({message:'x'})), 400, true), null);
eq('400 数组 → null', rejectionReason(replyFor(JSON.stringify([{error:'x'}])), 400, true), null);
eq('500 即使带原因也不判为拒绝', rejectionReason(replyFor(JSON.stringify({error:'服务错误'})), 500, true), null);
eq('502 纯文本原因也不判为拒绝', rejectionReason(replyFor('网关故障'), 502, false), null);
eq('200 不判为拒绝', rejectionReason(replyFor(JSON.stringify({error:'x'})), 200, true), null);
// 注意：reply 读取失败（null）由调用方在调用前直接按无法确认处理，不进入该函数——
// 这里确认函数对 null reply 不会误判
eq('回复为 null 时不抛错且不判拒绝', (()=>{try{return rejectionReason(null,400,true);}catch{return 'threw';}})(), 'threw');

console.log(`\n${fail===0 ? '全部通过' : fail+' 项失败'}：${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);
EOF
