@@ -352,6 +353,27 @@ function serviceReadableError(parsed, data, raw, trimJsonReason) {
   return (raw || "").trim().slice(0, 200);
 }

+// CSV 导入与批量修改共用的「整次操作是否被明确拒绝」判断，两处只需维护这一处：
